        critfail:{t:"盒子从你手里滑了出去，摔在地上。黑色的石头滚了出来，发出一声低沉的嗡鸣——街上的人都看了过来。李管事的脸白了。", effect:{flag:"relic_exposed", san:-5, relation:"li_guanshi:-15"}}
