      arr.push("「你很守规矩。」他说，「守规矩的人，活得久。」");
      arr.push("");
      arr.push("你走出客栈时，阳光刺得你眯了眯眼。你不知道盒子里是什么，但你知道那不是普通的货物。");
      arr.push("");
