      arr.push("承天山的云是有形状的。");
      arr.push("");
      arr.push("你在承天山下长大。你的父亲是书院的杂役，你从小就在书院里跑腿、偷听、看书。你没正式入学，但你比很多正式学生读的书都多。");
      arr.push("");
