        ok:{t:"你拆开信，但大部分内容你看不懂——是用古文写的。你只看懂了几个词：「七印」「原初之物」「真相」。你把信重新封好。", effect:{knowledge:1, san:-2}},
        fail:{t:"你想拆开信，但信封上有某种封印——你一碰到，手指就被灼伤了。你不敢再试。", effect:{hp:-5}},
        critfail:{t:"你拆开了信，但信的内容让你SAN值暴跌——你看到了一些你不该看到的东西。你赶紧把信烧掉了。", effect:{san:-15, flag:"destroyed_hlj_letter"}}
