      arr.push("接下来两天，你干活总走神。劈柴的时候，斧头落在柴墩边沿，木屑迸了一脸；给先生研墨，墨汁洒了半张纸。书院里的同窗笑你丢了魂，你也不辩解。只有你自己知道，那道光还烫在眼皮底下，闭上眼就能看见。");
