      arr.push("下山的路比上山好走，风却更大。承天山的背阴坡积着终年不化的残雪，松涛一阵一阵，从谷底翻上来，像有人在山腹里叹气。玄机子走在前头，步子不快不慢，灰褐色的衣摆被风掀起来，又落下去。");
      arr.push("");
