      arr.push("");
      arr.push("他指了指北面：「艾尔达大陆学院，墨丘利教授，七印研究。他能给你别的先生给不了的东西。」风把他最后半句话卷走了，你没听清，也没问。你只是把《七印考》又往怀里揣了揣，那本书的封皮是皮制的，磨得发亮，像被人翻过很多遍。");
      arr.push("");
      arr.push("出了山门，你最后回头看了一眼。承天山的主峰立在暮色里，云还是那个形状——像一只眼，半睁着。你想，它大概还会睁很久。");
